-- Golden Gate ({{ mode }}): its colours in Hyprland. Generated by rice-render;
-- hypr.lua loads it, and `rice mode` sends it on its own (hyprctl eval).

-- a hairline round every window, a touch stronger on the focused one
local edge_active   = "{{ colors.ink | hypr(0.22) }}"
local edge_inactive = "{{ colors.ink | hypr(0.10) }}"

hl.config({
    general = {
        col = {
            active_border   = edge_active,
            inactive_border = edge_inactive,
        },
    },

    decoration = {
        -- the frost: white and bright by day, smoked at night
        blur = {
            brightness = {{ meta.blur_brightness }},
            contrast   = {{ meta.blur_contrast }},
        },
        -- large and soft; the focused window's is stronger
        shadow = {
            range          = 48,
            color          = "{{ roles.shadow | hypr(meta.shadow_active) }}",
            color_inactive = "{{ roles.shadow | hypr(meta.shadow_inactive) }}",
        },
        dim_strength = {{ meta.dim_inactive }},
    },

    group = {
        col = {
            border_active   = edge_active,
            border_inactive = edge_inactive,
        },
    },

    misc = { background_color = "{{ roles.bg | hypr(ff) }}" },
})
